import datetime as dt
import unittest

import landed

NOW = dt.datetime(2026, 10, 3, 12, 0, tzinfo=dt.timezone.utc)


def e(path, when, how="changed", root="DEV"):
    return {"root": root, "path": path, "when": when, "how": how, "machine": "m"}


class TestProjects(unittest.TestCase):
    def test_most_specific_folder_wins_and_unmatched_paths_get_their_top_folder(self):
        idx = landed.project_index({"projects": [
            {"name": "Football", "dev_folder": "Football"},
            {"name": "SpeedProfiling", "dev_folder": "Football/SpeedProfiling"},
            {"name": "HPI_Protocol", "drive_folder": "01_PROJECTS/_STALLED/HighPerformanceInitative_RTP"},
        ]})
        self.assertEqual(landed.project_for(e("Football/SpeedProfiling/R/a.R", "x"), idx), "SpeedProfiling")
        self.assertEqual(landed.project_for(e("Football/other.txt", "x"), idx), "Football")
        self.assertEqual(landed.project_for(
            e("01_PROJECTS/_STALLED/HighPerformanceInitative_RTP/doc.docx", "x", root="DRIVE"), idx), "HPI_Protocol")
        self.assertEqual(landed.project_for(e("09_PRO_DEV/paper.pdf", "x", root="DRIVE"), idx), "(Drive) 09_PRO_DEV")


class TestPrivacy(unittest.TestCase):
    def test_athlete_and_health_paths_never_enter_the_ledger(self):
        for path in ("DexaProject/scan.csv", "02_SPORTS/Football/FA2026/NEW PERCH FB ROSTER_UPLOAD.xlsx",
                     "08_ADMIN/Personnel/Linda_Mungai/x.pdf", "02_SPORTS/Football/Injury_Surveillance/a.csv"):
            self.assertFalse(landed.keep(e(path, "x", root="DRIVE")), path)
        self.assertTrue(landed.keep(e("09_PRO_DEV/Research_Papers/a.pdf", "x", root="DRIVE")))


class TestMerge(unittest.TestCase):
    def test_keeps_latest_per_path_drops_old_and_new_stays_new(self):
        old = [e("a.md", "2026-10-01T10:00:00+00:00", "new"), e("old.md", "2026-08-01T10:00:00+00:00")]
        new = [e("a.md", "2026-10-03T09:00:00+00:00", "changed"), e("b.md", "2026-10-02T09:00:00+00:00")]
        merged = landed.merge(old, new, NOW)
        self.assertEqual([m["path"] for m in merged], ["a.md", "b.md"])
        self.assertEqual(merged[0]["how"], "new")
        self.assertEqual(merged[0]["when"], "2026-10-03T09:00:00+00:00")


if __name__ == "__main__":
    unittest.main()
